def re_order(A):
    """Write a function to move all zeroes to the end of the given array."""
    non_zero = [x for x in A if x != 0]
    ordered = non_zero + [0] * (len(A) - len(non_zero))
    if isinstance(A, list):
        A[:] = ordered
        return A
    return ordered
